  ('pt-d8', 7, '{"schemaVersion":1,"routeId":"pt-d8","number":7,"corrects":6,"title":"D8 residence visa for remote work for employers or clients abroad","country":"PT","tags":["digital-nomad","temporary-residence"],"effectiveFrom":"2026-01-01","status":"open","currency":"EUR","sources":[{"id":"lei-23-2007","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007 (foreigners law), articles 58.º, n.º 5, and 99.º, n.os 1 and 4: the family members who may apply with the principal, and the other parent''s consent for a child of only one spouse","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-age","url":"https://diariodarepublica.pt/dr/detalhe/lei/61-2025-941547426","title":"Lei n.º 23/2007, article 99.º, n.º 6: the marriage or de facto union must be valid and recognized under Portuguese law, and both spouses or partners 18 or over on the date of the application","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2025/10/20400/0000900017.pdf"},{"id":"lei-23-2007-partner","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 100.º, n.º 1: reunification may be authorized with the partner in a duly proven de facto union and the partner''s unmarried minor or incapable children entrusted to the partner","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-entry-ban","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 52.º, n.º 1, a) to c): no visa during an entry ban that follows a removal, or under an alert for return or for refusal of entry and stay","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-conviction","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 52.º, n.º 3: a residence visa is refused after a conviction for a crime Portugal punishes with more than one year of prison, even if not served or suspended","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-visa-validity","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 58.º, n.º 2: a residence visa is valid for two entries and lets its holder stay for four months","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-visa-decision","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 58.º, n.º 4: the residence visa application is decided within 60 days","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-permit","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 75.º, n.º 1: a temporary residence permit is valid for two years from the issue of the card and renewable for successive periods of three years","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-fees","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 209.º, n.º 1: the fees for visas granted by consular posts are those of the table of consular fees","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-scope","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 4.º: the law covers foreigners and stateless persons, not nationals of EU or EEA states or of a state with an EU free movement agreement","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"lei-23-2007-remote","url":"https://diariodarepublica.pt/dr/detalhe/lei/18-2022-200268064","title":"Lei n.º 23/2007, article 61.º-B: residence visa for employees and independent professionals who work remotely for persons domiciled or seated outside Portugal, the work link being shown","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/08/16400/0000200137.pdf"},{"id":"dr-84-2007-income","url":"https://diariodarepublica.pt/dr/detalhe/decreto-regulamentar/4-2022-201699171","title":"Decreto Regulamentar n.º 84/2007, article 31.º-A, n.º 1, c): proof of average monthly income from work over the last three months of at least four guaranteed minimum monthly wages","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/09/19000/0002800097.pdf"},{"id":"dr-84-2007-work-link","url":"https://diariodarepublica.pt/dr/detalhe/decreto-regulamentar/4-2022-201699171","title":"Decreto Regulamentar n.º 84/2007, article 31.º-A, n.º 1, a) and b): a work contract or employer''s statement, or a company contract, a services contract or proof of services provided","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://files.diariodarepublica.pt/1s/2022/09/19000/0002800097.pdf"},{"id":"portaria-1563-2007","url":"https://diariodarepublica.pt/dr/detalhe/portaria/1563-2007-628798","title":"Portaria n.º 1563/2007, article 2.º, n.º 2: means per household member against the minimum wage net of social security: first adult 100%, other adults 50%, under 18 and dependent adult children 30%","kind":"official","verifiedAt":"2026-11-20","machineReadableUr